const commits = $('Get Commits').all().map(item => item.json);
const prs = $('Get Pull Requests').all().map(item => item.json);
const issues = $('Get Issues').all().map(item => item.json).filter(item => !item.pull_request);

const events = [];
const evidence = [];
const decisions = [];

const project = 'Context Recovery Engine';
const repository = 'priyanshukumarverma091-hub/RETRO-AI';

function makeEvidence(id, type, claim, description, sourceEventIds, confidence, metadata = {}) {
  return {
    id,
    evidence_type: type,
    claim,
    description,
    source_event_ids: sourceEventIds,
    confidence,
    project,
    metadata
  };
}

function text(value) {
  return String(value || '').trim();
}

function hasAny(value, words) {
  const lower = text(value).toLowerCase();
  return words.some(word => lower.includes(word));
}

// ============================================================
// COMMITS
// ============================================================

for (const commit of commits) {
  const sha = commit.sha;
  const eventId = `github-commit-${sha}`;
  const message = text(commit.commit?.message);
  const title = message.split('\n')[0] || 'GitHub commit';
  const actor = commit.commit?.author?.name || commit.author?.login || 'unknown';

  events.push({
    id: eventId,
    source: 'github',
    source_id: sha,
    event_type: 'commit',
    actor,
    timestamp: commit.commit?.author?.date || new Date().toISOString(),
    project,
    title,
    content: message,
    url: commit.html_url || null,
    references: [],
    metadata: {
      repository,
      sha
    }
  });

  if (hasAny(message, ['fix', 'fixed', 'bug', 'error', 'issue', 'resolve', 'resolved'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-problem`,
        'problem',
        title,
        message,
        [eventId],
        0.85,
        { source: 'commit', sha }
      )
    );
  }

  if (hasAny(message, ['implement', 'implemented', 'add', 'added', 'complete', 'completed', 'build', 'built', 'create', 'created'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-solution`,
        'solution',
        title,
        message,
        [eventId],
        0.80,
        { source: 'commit', sha }
      )
    );
  }

  if (hasAny(message, ['decide', 'decided', 'decision', 'chosen', 'choose', 'switch', 'use ', 'using '])) {
    const evidenceId = `evidence-${eventId}-decision`;

    evidence.push(
      makeEvidence(
        evidenceId,
        'decision',
        title,
        message,
        [eventId],
        0.70,
        { source: 'commit', sha }
      )
    );

    decisions.push({
      id: `decision-${eventId}`,
      title,
      decision: message,
      problem: null,
      alternatives: [],
      reason: null,
      status: 'implemented',
      evidence_ids: [evidenceId],
      decided_by: [actor],
      project,
      metadata: {
        source: 'github_commit',
        sha
      }
    });
  }

  if (hasAny(message, ['todo', 'pending', 'remaining', 'next step', 'next:', 'follow up', 'follow-up'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-task`,
        'task',
        title,
        message,
        [eventId],
        0.75,
        { source: 'commit', sha }
      )
    );
  }

  if (hasAny(message, ['depends on', 'blocked by', 'requires', 'required by'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-dependency`,
        'dependency',
        title,
        message,
        [eventId],
        0.80,
        { source: 'commit', sha }
      )
    );
  }
}

// ============================================================
// PULL REQUESTS
// ============================================================

for (const pr of prs) {
  const eventId = `github-pr-${pr.id}`;
  const title = text(pr.title) || 'Pull Request';
  const body = text(pr.body);
  const content = `${title}\n${body}`.trim();
  const actor = pr.user?.login || 'unknown';
  const merged = pr.merged_at !== null;

  events.push({
    id: eventId,
    source: 'github',
    source_id: String(pr.id),
    event_type: 'pull_request',
    actor,
    timestamp: pr.updated_at || pr.created_at || new Date().toISOString(),
    project,
    title,
    content,
    url: pr.html_url || null,
    references: [],
    metadata: {
      repository,
      number: pr.number,
      state: pr.state,
      merged,
      draft: pr.draft || false
    }
  });

  if (merged) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-status`,
        'status_change',
        `Pull Request #${pr.number} was merged: ${title}`,
        content,
        [eventId],
        0.95,
        { source: 'pull_request', number: pr.number, merged: true }
      )
    );
  }

  if (hasAny(content, ['fix', 'bug', 'error', 'resolve', 'resolved'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-problem`,
        'problem',
        title,
        content,
        [eventId],
        0.85,
        { source: 'pull_request', number: pr.number }
      )
    );
  }

  if (hasAny(content, ['implement', 'implemented', 'feature', 'add', 'added', 'refactor'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-solution`,
        'solution',
        title,
        content,
        [eventId],
        0.82,
        { source: 'pull_request', number: pr.number }
      )
    );
  }

  if (hasAny(content, ['decided', 'decision', 'chosen', 'choose', 'switch to', 'use '])) {
    const evidenceId = `evidence-${eventId}-decision`;

    evidence.push(
      makeEvidence(
        evidenceId,
        'decision',
        title,
        content,
        [eventId],
        0.70,
        { source: 'pull_request', number: pr.number }
      )
    );

    decisions.push({
      id: `decision-${eventId}`,
      title,
      decision: content,
      problem: null,
      alternatives: [],
      reason: null,
      status: merged ? 'implemented' : 'accepted',
      evidence_ids: [evidenceId],
      decided_by: [actor],
      project,
      metadata: {
        source: 'github_pull_request',
        number: pr.number
      }
    });
  }

  if (hasAny(content, ['depends on', 'blocked by', 'requires', 'required by'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-dependency`,
        'dependency',
        title,
        content,
        [eventId],
        0.82,
        { source: 'pull_request', number: pr.number }
      )
    );
  }
}

// ============================================================
// ISSUES
// ============================================================

for (const issue of issues) {
  const eventId = `github-issue-${issue.id}`;
  const title = text(issue.title) || 'Issue';
  const body = text(issue.body);
  const content = `${title}\n${body}`.trim();
  const actor = issue.user?.login || 'unknown';
  const closed = issue.state === 'closed';

  events.push({
    id: eventId,
    source: 'github',
    source_id: String(issue.id),
    event_type: 'issue',
    actor,
    timestamp: issue.updated_at || issue.created_at || new Date().toISOString(),
    project,
    title,
    content,
    url: issue.html_url || null,
    references: [],
    metadata: {
      repository,
      number: issue.number,
      state: issue.state,
      labels: (issue.labels || []).map(label => label.name)
    }
  });

  if (closed) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-status`,
        'status_change',
        `Issue #${issue.number} was closed: ${title}`,
        content,
        [eventId],
        0.95,
        { source: 'issue', number: issue.number, state: 'closed' }
      )
    );
  } else {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-task`,
        'task',
        `Open issue: ${title}`,
        content,
        [eventId],
        0.90,
        { source: 'issue', number: issue.number, state: 'open' }
      )
    );
  }

  if (hasAny(content, ['fix', 'bug', 'error', 'problem', 'failure'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-problem`,
        'problem',
        title,
        content,
        [eventId],
        0.88,
        { source: 'issue', number: issue.number }
      )
    );
  }

  if (hasAny(content, ['depends on', 'blocked by', 'requires', 'required by'])) {
    evidence.push(
      makeEvidence(
        `evidence-${eventId}-dependency`,
        'dependency',
        title,
        content,
        [eventId],
        0.82,
        { source: 'issue', number: issue.number }
      )
    );
  }
}

// ============================================================
// DEDUPLICATE EVIDENCE
// ============================================================

const uniqueEvidence = [];
const seenEvidence = new Set();

for (const item of evidence) {
  const key = `${item.evidence_type}|${item.claim}|${item.source_event_ids.join(',')}`;

  if (!seenEvidence.has(key)) {
    seenEvidence.add(key);
    uniqueEvidence.push(item);
  }
}

return [
  {
    json: {
      events,
      evidence: uniqueEvidence,
      decisions,
      target_role: 'New Team Member',
      previous_owner: 'Priyanshu',
      extraction_summary: {
        events: events.length,
        evidence: uniqueEvidence.length,
        decisions: decisions.length,
        problems: uniqueEvidence.filter(e => e.evidence_type === 'problem').length,
        solutions: uniqueEvidence.filter(e => e.evidence_type === 'solution').length,
        tasks: uniqueEvidence.filter(e => e.evidence_type === 'task').length,
        dependencies: uniqueEvidence.filter(e => e.evidence_type === 'dependency').length,
        status_changes: uniqueEvidence.filter(e => e.evidence_type === 'status_change').length
      }
    }
  }
];

const response = $json;
const extraction = $('Extract Evidence').first().json.extraction_summary;

return [
  {
    json: {
      status: response.status || 'unknown',
      extraction_summary: extraction,
      target_role: response.target_role || 'New Team Member',
      previous_owner: response.previous_owner || null,
      timeline_events: response.timeline_events || 0,
      evidence_count: response.evidence_count || 0,
      decision_count: response.decision_count || 0,
      dependencies: response.dependencies || 0,
      takeover_report: response.report || null
    }
  }
];
